"""Regenerate the checked-in MSBuild Content map from the frozen runtime allowlist."""
import html
import json
import sys
from pathlib import Path

repo = Path(__file__).resolve().parents[2]
manifest = json.loads((repo / "docs/design-v2/final/runtime-package.json").read_text(encoding="utf-8"))
lines = [
    "<!-- Generated by python src/PokeCorner.App/generate-runtime-props.py from docs/design-v2/final/runtime-package.json. -->",
    "<Project>",
    "  <ItemGroup>",
]
seen = set()
for item in manifest["files"]:
    source, target = item["path"], item["target"]
    if not source.startswith("docs/") or any(p in ("", ".", "..") for p in source.split("/")):
        raise ValueError(f"Unsafe source: {source}")
    if any(p in ("", ".", "..") for p in target.split("/")) or target in seen:
        raise ValueError(f"Unsafe or duplicate target: {target}")
    if not (repo / source).is_file():
        raise FileNotFoundError(source)
    seen.add(target)
    include = html.escape(str(Path("..") / ".." / source), quote=True)
    link = html.escape(str(Path("Data") / target), quote=True)
    lines.append(f'    <Content Include="{include}" Link="{link}" CopyToOutputDirectory="PreserveNewest" />')
lines += ["  </ItemGroup>", "</Project>"]
output = Path(__file__).with_name("RuntimePackage.props")
generated = "\n".join(lines) + "\n"
if "--check" in sys.argv:
    if output.read_text(encoding="utf-8") != generated:
        raise SystemExit("RuntimePackage.props is stale")
else:
    output.write_text(generated, encoding="utf-8")
print(f"{len(seen)} runtime package files")
